            res[i][j]=g[s[0]][s[1]]
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=i+di,j+dj
                if 0<=ni<h and 0<=nj<w and g[ni][nj]!=0 and thick[ni][nj] and (ni,nj) not in seen:
                    seen.add((ni,nj)); q.append((ni,nj))
